'use strict';

/**
 * Generated by `aid infra gen`. Do not edit: the next run refuses to overwrite a
 * hand-edited file, and the construct carries no project-specific fact to keep.
 *
 * The AWS CDK spelling of `infra/generated/modules/serverless`: one container-image Lambda
 * per `serverless` service and one HTTP API routing each pipeline endpoint at its service.
 * It reads the same context document the module reads, so the two backends cannot drift.
 *
 * Business inputs stay inputs: the image each service runs, the ARN of each secret, and
 * per-service sizing arrive in `inputs`, never in the generated tree.
 */

const cdk = require('aws-cdk-lib');
const apigwv2 = require('aws-cdk-lib/aws-apigatewayv2');
const bedrock = require('aws-cdk-lib/aws-bedrock');
const iam = require('aws-cdk-lib/aws-iam');
const lambda = require('aws-cdk-lib/aws-lambda');

/** Lambda names allow letters, digits, hyphens and underscores; a namespace may carry a dot. */
function nameOf(project, id) {
  return (project.namespace + '-' + project.name + '-' + id)
    .replace(/[^A-Za-z0-9-_]/g, '-')
    .slice(0, 64);
}

/**
 * Provision the managed guardrail for one service, and nothing when the spec leaves it to
 * its operator.
 *
 * The HCL module spells the same two resources, so the two backends must agree about which
 * service owns a guardrail and which immutable version the app calls. A spec that names
 * the engine but carries no policy block owns no guardrail here either.
 */
function addGuardrail(scope, context, id, service, role) {
  if (!(service.guardrailEngines || []).includes('bedrock')) return undefined;

  const policy = (context.guardrails || {})[id];
  if (!policy) return undefined;

  // A guardrail name caps at 50 characters and allows letters, digits, hyphens and
  // underscores; `nameOf` is already sanitised, so only the cap is left.
  const props = {
    name: (nameOf(context.project, id) + '-guardrail').slice(0, 50),
    description: policy.message,
    blockedInputMessaging: policy.message,
    blockedOutputsMessaging: policy.message,
  };

  if (policy.content.length > 0) {
    props.contentPolicyConfig = {
      filtersConfig: policy.content.map((filter) => ({
        type: filter.type,
        inputStrength: filter.strength,
        outputStrength: filter.strength,
      })),
    };
  }

  if (policy.topics.length > 0) {
    props.topicPolicyConfig = {
      topicsConfig: policy.topics.map((topic) => ({
        name: topic.name,
        definition: topic.definition,
        type: 'DENY',
      })),
    };
  }

  // Only the author's own words, never a managed list: adding one here would block
  // vocabulary the spec did not ask for.
  if (policy.words.length > 0) {
    props.wordPolicyConfig = {
      wordsConfig: policy.words.map((text) => ({ text: text })),
    };
  }

  if (policy.pii.length > 0) {
    props.sensitiveInformationPolicyConfig = {
      piiEntitiesConfig: policy.pii.map((entity) => ({
        type: entity.type,
        action: entity.action,
      })),
    };
  }

  const guardrail = new bedrock.CfnGuardrail(scope, id + 'Guardrail', props);

  // A guardrail is mutable and every change mints a new immutable version, so the app is
  // pinned to this one. Pointing it at DRAFT would let a later edit change a live
  // deployment without a plan.
  const version = new bedrock.CfnGuardrailVersion(scope, id + 'GuardrailVersion', {
    guardrailIdentifier: guardrail.attrGuardrailId,
    description: 'Published by aid infra gen from the spec.',
  });

  // Evaluating a guardrail is the app's job; provisioning it is this construct's. Scoping
  // the grant to the ARN means a compromised function cannot apply another guardrail.
  role.addToPolicy(
    new iam.PolicyStatement({
      actions: ['bedrock:ApplyGuardrail'],
      resources: [guardrail.attrGuardrailArn],
    }),
  );

  return { guardrail: guardrail, version: version };
}

/**
 * Add every `serverless` service in `context` to `scope`.
 *
 * A refusal throws with the same sentence the OpenTofu module puts in a precondition, so
 * `cdk synth` fails for the reason `tofu plan` would: streaming cannot be delivered by an
 * HTTP API, a service needs an image, and a declared secret needs its ARN.
 */
function addServerless(scope, context, inputs) {
  const functions = {};
  const routed = [];
  const secretArns = inputs.secretArns || {};

  for (const id of Object.keys(context.services)) {
    const service = context.services[id];
    if (service.target !== 'serverless') continue;

    if (service.streaming) {
      throw new Error(
        'Service "' + id + '" declares streaming, which an HTTP API cannot deliver on AWS. ' +
          'Serve it from a container target here, or deploy it as serverless on GCP, where ' +
          'Cloud Run streams.',
      );
    }

    const image = (inputs.images || {})[id];
    if (!image) {
      throw new Error(
        'No images entry for "' + id + '". Name the released tag this service runs; ' +
          'the spec names a repository, not a tag.',
      );
    }

    for (const variable of service.env) {
      if (variable.secret && !secretArns[variable.name]) {
        throw new Error(
          'Service "' + id + '" references a secret with no secretArns entry. ' +
            'Add name -> ARN for every secret it declares.',
        );
      }
    }

    const role = new iam.Role(scope, id + 'Role', {
      roleName: nameOf(context.project, id) + '-role',
      assumedBy: new iam.ServicePrincipal('lambda.amazonaws.com'),
      managedPolicies: [
        iam.ManagedPolicy.fromAwsManagedPolicyName('service-role/AWSLambdaBasicExecutionRole'),
        // A container-image function pulls from ECR with this role, and the repository a
        // release pushes to is private by default. Mirrors the HCL module's ecr
        // attachment; the managed policy is account-scoped by the token ECR returns.
        iam.ManagedPolicy.fromAwsManagedPolicyName('AmazonEC2ContainerRegistryReadOnly'),
      ],
    });

    const declaredSecrets = service.env.filter((variable) => variable.secret);
    if (declaredSecrets.length > 0 && Object.keys(secretArns).length > 0) {
      role.addToPolicy(
        new iam.PolicyStatement({
          actions: ['secretsmanager:GetSecretValue'],
          resources: Object.keys(secretArns).map((name) => secretArns[name]),
        }),
      );
    }

    const usesBedrock = (service.providers || []).includes('bedrock');
    if (usesBedrock) {
      role.addToPolicy(
        new iam.PolicyStatement({
          actions: ['bedrock:InvokeModel'].concat(
            service.streaming ? ['bedrock:InvokeModelWithResponseStream'] : [],
          ),
          resources: [
            'arn:' + cdk.Aws.PARTITION + ':bedrock:*::foundation-model/*',
            'arn:' +
              cdk.Aws.PARTITION +
              ':bedrock:*:' +
              cdk.Aws.ACCOUNT_ID +
              ':inference-profile/*',
          ],
        }),
      );
    }

    // Retrieve is the only call a managed base is used for: generation stays in this
    // project, where the model gate, the guardrail and the cost ledger can see it. The
    // grant goes to every serverless service, as the HCL module gives it, because the
    // retrievers a service binds are a spec fact and the base is one resource.
    //
    // The id and ARN arrive in `inputs` rather than the context: the context is written
    // before anything is applied, so it can only say which base the spec declared. A base
    // with no input entry does not exist yet, and a policy with an empty resource is
    // invalid rather than merely empty -- the same reason the secrets grant is gated.
    const providedBases = inputs.knowledgeBases || {};
    const declaredBases = context.knowledgeBases || {};
    const bases = Object.keys(declaredBases)
      .filter((baseId) => declaredBases[baseId].engine === 'aws-bedrock' && providedBases[baseId])
      .map((baseId) =>
        Object.assign({}, declaredBases[baseId], {
          id: providedBases[baseId].id,
          arn: providedBases[baseId].arn,
        }),
      );
    const existingBases = bases.filter((base) => base.id && base.arn);
    if (existingBases.length > 0) {
      role.addToPolicy(
        new iam.PolicyStatement({
          actions: ['bedrock:Retrieve'],
          resources: existingBases.map((base) => base.arn),
        }),
      );
    }

    const variables = {};
    if (usesBedrock) variables.AWS_REGION = inputs.bedrockRegion || cdk.Aws.REGION;

    const managed = addGuardrail(scope, context, id, service, role);
    if (managed) {
      variables.BEDROCK_GUARDRAIL_ID = managed.guardrail.attrGuardrailId;
      variables.BEDROCK_GUARDRAIL_VERSION = managed.version.attrVersion;
    }

    // Only a service that binds one of the base's retrievers learns the id, and only
    // once the base exists: the runtime raises a named error for a missing id, while an
    // empty string would read as a created base with an empty corpus.
    for (const base of existingBases) {
      const bound = (base.retrievers || []).some((retriever) =>
        (service.ingest || []).includes(retriever),
      );
      if (bound) variables[base.envName] = base.id;
    }

    for (const variable of service.env) {
      if (variable.secret) {
        variables[variable.name] =
          '{{resolve:secretsmanager:' + secretArns[variable.name] + ':SecretString}}';
      } else if (variable.value !== undefined) {
        variables[variable.name] = variable.value;
      }
    }

    const sizing = (inputs.sizing || {})[id] || {};
    const tags = inputs.tags || {};
    const fn = new lambda.CfnFunction(scope, id + 'Function', {
      functionName: nameOf(context.project, id),
      role: role.roleArn,
      packageType: 'Image',
      code: { imageUri: image },
      memorySize: sizing.memoryMb || 1024,
      timeout: sizing.timeoutSeconds || 30,
      environment: { variables: variables },
      tags: Object.keys(tags).map((key) => ({ key: key, value: tags[key] })),
    });

    functions[id] = fn;
    routed.push({ id: id, service: service, fn: fn });
  }

  const withRoutes = routed.filter((entry) => entry.service.routes.length > 0);
  if (withRoutes.length === 0) return functions;

  const api = new apigwv2.CfnApi(scope, 'HttpApi', {
    name: context.project.namespace + '-' + context.project.name,
    protocolType: 'HTTP',
  });

  new apigwv2.CfnStage(scope, 'HttpApiDefaultStage', {
    apiId: api.ref,
    stageName: '$default',
    autoDeploy: true,
  });

  const integrations = {};
  for (const entry of routed) {
    integrations[entry.id] = new apigwv2.CfnIntegration(scope, entry.id + 'Integration', {
      apiId: api.ref,
      integrationType: 'AWS_PROXY',
      integrationUri:
        'arn:' +
        cdk.Aws.PARTITION +
        ':apigateway:' +
        cdk.Aws.REGION +
        ':lambda:path/2015-03-31/functions/' +
        entry.fn.attrArn +
        '/invocations',
      payloadFormatVersion: '2.0',
    });
  }

  for (const entry of withRoutes) {
    for (const route of entry.service.routes) {
      new apigwv2.CfnRoute(scope, entry.id + 'Route ' + route.method + ' ' + route.path, {
        apiId: api.ref,
        routeKey: route.method + ' ' + route.path,
        target: 'integrations/' + integrations[entry.id].ref,
      });
    }
  }

  for (const entry of withRoutes) {
    new lambda.CfnPermission(scope, entry.id + 'Invoke', {
      action: 'lambda:InvokeFunction',
      functionName: entry.fn.ref,
      principal: 'apigateway.amazonaws.com',
      sourceArn: api.attrExecuteApiArn + '/*/*',
      sourceAccount: cdk.Aws.ACCOUNT_ID,
    });
  }

  new cdk.CfnOutput(scope, 'ApiEndpoint', {
    description: 'The HTTP API base URL.',
    value:
      'https://' + api.ref + '.execute-api.' + cdk.Aws.REGION + '.' + cdk.Aws.URL_SUFFIX,
  });

  return functions;
}

module.exports = { addServerless: addServerless };
